import os
root = r'D:\qqhru.edu.cn\日新Rx102科研组 - General\openscience\PCM材料在TPMS晶格下的实验分析研究'
skip = {'.git','node_modules','__pycache__','.openscience'}
# 经典 GBK/UTF-8 互转产生的乱码字样
markers = ['锟斤拷','锟','鈥','â€œ','â€','ï¿½','æ¥','ç','ä¸','é£','鍦','涓','鏂','鐩','鎬','杩','鏈','鍥','瀵','鏄','鐨','涓\x8b']
hits = {}
for dp, dn, fn in os.walk(root):
    dn[:] = [d for d in dn if d not in skip]
    for f in fn:
        p = os.path.join(dp,f)
        ext = os.path.splitext(f)[1].lower()
        if ext in ('.png','.pdf','.docx','.xlsx','.pyc','.jpg','.jpeg'):
            continue
        try:
            txt = open(p,'r',encoding='utf-8',errors='strict').read()
        except Exception:
            continue
        for m in markers:
            if m in txt:
                hits.setdefault(p, set()).add(m)
for p, ms in sorted(hits.items()):
    print(os.path.relpath(p, root), '->', list(ms))
print('total:', len(hits))
